"""Report previous-month-only delay deviations and source/cause audits."""
from pathlib import Path
from collections import defaultdict
import csv,json,os
import numpy as np
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'data/ml/delay_shift_audit_20261013'
os.environ['MPLCONFIGDIR']=str(OUT/'tmp/matplotlib');Path(os.environ['MPLCONFIGDIR']).mkdir(parents=True,exist_ok=True)
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def table(rows,fields):
 return '\n'.join(['| '+' | '.join(k for k,f in fields)+' |','| '+' | '.join('---' for _ in fields)+' |']+['| '+' | '.join(str(f(r)) for _,f in fields)+' |' for r in rows])
def main():
 r=json.loads((OUT/'result.json').read_text());raw=json.loads((OUT/'raw-receipt-result.json').read_text());plan=json.loads((OUT/'raw-plan-reconciliation.json').read_text());proof=json.loads((OUT/'raw-plan-validation.json').read_text())
 trips=list(csv.DictReader((OUT/'trip-comparison.csv').open()));supported=[x for x in trips if x['supported']=='True']
 stops=list(csv.DictReader((OUT/'stop-comparison.csv').open()));stations=defaultdict(list)
 for x in stops:
  if int(x['august_dates'])>=10:stations[x['station']].append(x)
 station_stats=[{'station':name,'pairs':len(xs),'mean':float(np.mean([float(x['deviation_min']) for x in xs])),'median':float(np.median([float(x['deviation_min']) for x in xs]))} for name,xs in stations.items()]
 top=sorted((x for x in station_stats if x['pairs']>=30),key=lambda x:-x['mean'])[:15]
 munich=[x for x in station_stats if x['station'] in ('München Ost','München Donnersbergerbrücke','München Karlsplatz','München Hbf (tief)','München Rosenheimer Platz','München Hackerbrücke')]
 cause_groups={}
 for label,predicate in [('works valid on trip',lambda x:x['valid_works_trip']=='True'),('disruption valid, no works',lambda x:x['valid_works_trip']!='True' and x['valid_disruption_trip']=='True'),('recorded message, no qualifying works/disruption',lambda x:x['recorded_message']=='True' and x['valid_works_trip']!='True' and x['valid_disruption_trip']!='True'),('no recorded message',lambda x:x['recorded_message']!='True')]:
  vals=np.array([float(x['deviation_min']) for x in supported if predicate(x)])
  cause_groups[label]={'trips':len(vals),'mean':float(vals.mean()) if len(vals) else None,'median':float(np.median(vals)) if len(vals) else None}
 dates=sorted(r['daily_matched_deviation']);fig,ax=plt.subplots(1,2,figsize=(13,4.7),layout='constrained')
 delta=np.array([float(x['deviation_min']) for x in supported]);ax[0].hist(delta,bins=70,color='#246EAF');ax[0].axvline(0,color='black',lw=1);ax[0].set(xlabel='September 15 mean minus August mean (minutes)',ylabel='Recurring trips',title='Supported recurring trips; one vote per August date')
 ax[1].plot(range(len(dates)),[r['daily_matched_deviation'][d]['mean_min'] for d in dates],marker='o',label='Mean');ax[1].plot(range(len(dates)),[r['daily_matched_deviation'][d]['median_min'] for d in dates],marker='.',label='Median');ax[1].axhline(0,color='black',lw=1);ax[1].set(xticks=range(len(dates)),xticklabels=[d[5:] for d in dates],ylabel='Deviation from August average (minutes)',title='Matched September trend; available trips vary by date');ax[1].tick_params(axis='x',rotation=45);ax[1].legend()
 fig.savefig(OUT/'august-deviation.svg');fig.savefig(OUT/'august-deviation.png',dpi=160);plt.close(fig)
 rng=np.random.default_rng(20261013);boot=np.array([delta[rng.integers(0,len(delta),len(delta))].mean() for _ in range(1000)]) if len(delta) else np.array([np.nan])
 ci=np.quantile(boot,[.025,.975]);group_summary={**r['comparison'],'trip_cluster_bootstrap_mean_interval':ci.tolist(),'causes_partitioned':cause_groups,'munich_station_pairs':munich,'top_station_deviations':top}
 (OUT/'report-summary.json').write_text(json.dumps(group_summary,indent=2))
 fmt=lambda x:'—' if x is None else f'{x:.2f}'
 shared=[('Group',lambda x:x['label']),('Trips',lambda x:x['trips']),('Mean deviation (min)',lambda x:fmt(x['mean_deviation_min'])),('Median deviation (min)',lambda x:fmt(x['median_deviation_min']))]
 seg=[{'label':k,**v} for k,v in r['by_segment'].items()]
 sf=[('Station',lambda x:x['station']),('Supported train-stop pairs',lambda x:x['pairs']),('Mean deviation (min)',lambda x:fmt(x['mean'])),('Median deviation (min)',lambda x:fmt(x['median']))]
 coverage=list(csv.DictReader((OUT/'date-coverage.csv').open()))
 cf=[('Date',lambda x:x['date']),('Eligible arrivals',lambda x:f"{int(x['eligible_arrivals']):,}"),('Exact matched stop rows',lambda x:f"{int(x['exact_stop_matched']):,}"),('Matched trips with validity-overlapping works',lambda x:x['matched_trips_with_valid_works'])]
 lines=['---','kind: spec','title: "September 15 versus August: early-label and delay-cause investigation"','---','','# Investigation results before fitting','',
 f"**{len(supported):,} supported recurring trips** were compared with their **August 1–31 average only**. Mean September 15 deviation: **{r['comparison']['mean_deviation_min']:+.2f} minutes**; median **{r['comparison']['median_deviation_min']:+.2f} minutes**. Shares exceeding their August mean by 5 / 15 / 30 minutes: **{100*r['comparison']['share_over_5_min']:.2f}% / {100*r['comparison']['share_over_15_min']:.2f}% / {100*r['comparison']['share_over_30_min']:.2f}%**.",'',
 '![August-only comparison](../data/ml/delay_shift_audit_20261013/august-deviation.png)','',
 '## Cohort and matching','',
 f"September 15 has {r['september15_prepared_arrivals']:,} eligible prepared arrivals across {r['september15_recurring_trips']:,} recurring trips. {r['all_matched']['trips']:,} trips have qualifying August observations; {len(supported):,} have at least ten August run dates. Matching requires identical recurring train ID, source, route path, station and stop sequence. Each August run mean gets one vote, provided at least 80% of the fixed common stops are observed. Stops without August matches are excluded explicitly; no identity is merged by name.",'',
 'These restrictions improve comparability but exclude changed-route and changed-ID services, which could themselves be affected by works. No cross-identity pair has yet been independently verified. Results describe the matched population, not all September trips. An absent or cancelled arrival is not assigned zero delay. Service-pattern and weekday differences remain limitations; there is no weekday-only or partial-August delay baseline.','',
 f"A descriptive 95% bootstrap interval for the matched-trip mean is [{ci[0]:+.2f}, {ci[1]:+.2f}] minutes, resampling whole recurring-trip deviations (1,000 deterministic draws). This keeps each trip’s stops together, but does not account for shared region-wide events or correlated August dates; it is not a causal/generalization confidence interval.",'',table(seg,shared),'',
 '## Munich September 15 hotspots','',table(munich,sf),'',
 'These station numbers average supported recurring train-stop deviations; they are not independently sampled trips or a second baseline.','',
 '## Highest supported station deviations','',table(top,sf),'',
 '## Early-arrival label audit','',
 f"All **{r['early_audit']['rows']:,}** prepared targets below −5 minutes on September 6–19 match the stored arrival-delay seconds and the reconstructed actual-minus-scheduled timestamps. Prepared/database mismatches: **{r['early_audit']['prepared_vs_database_mismatch']}**; timestamp/delay mismatches: **{r['early_audit']['timestamp_vs_delay_mismatch']}**; missing actual timestamps: **{r['early_audit']['actual_timestamp_missing']}**.",'',
 table([{'threshold':f'Below −{t} minutes','count':r['early_audit'][f'below_minus_{t}']} for t in (5,15,30,60)],[('Threshold',lambda x:x['threshold']),('Arrivals',lambda x:f"{x['count']:,}")]),'',
 f"The raw plan/change reconciliation inspected **{plan['counts'].get('target_negative_stops',0):,} negative RE 161xx stops** on September 15. **{plan['counts'].get('source_confirmed_negative_pairs',0):,}** have both the database’s scheduled timestamp in a raw plan and its actual timestamp in a raw change response. Source hashes and timestamp values are retained in the reconciliation CSV. The independent provenance pass verifies {proof['unique_source_plans_verified']} unique raw plans and matching actual timestamps. None of these stored schedules agrees with the raw plan. Using those plans changes the mean from {proof['current_mean_target_min']:.2f} minutes to {proof['proposed_mean_target_min']:+.2f} minutes; none remains earlier than −5 minutes. This identifies a concrete schedule/label discrepancy, rather than a model prediction problem. The source path pins station-pattern times when a sequence first appears (`ingest/runs.py`) and later resolves trip schedules from that reusable pattern (`changes_poller._load_patterns`), without a per-service-date planned-time snapshot. That mechanism can retain obsolete times when the same route operates on a revised timetable. No source facts or labels have been changed; correction scope must cover training and evaluation consistently, not just these discovered misses. **None of the 282 raw plans was observed in the retained archive before its corrected five-hour forecast cutoff.** They substantiate the retrospective schedule discrepancy, but cannot be inserted into forecast-time features as though their receipt before cutoff were proven. Approved correction policy must distinguish target reference schedules from point-in-time inputs; missing availability remains explicit.",'',
 '## Construction and delay-cause evidence','',
 table([{'label':k,**v} for k,v in cause_groups.items()],[('Retrospective cohort',lambda x:x['label']),('Supported trips',lambda x:x['trips']),('Mean deviation (min)',lambda x:fmt(x['mean'])),('Median deviation (min)',lambda x:fmt(x['median']))]),'',
 'These cohorts collapse versions using source timestamps, exclude latest deleted notices and require explicit validity overlap. Trip-wide overlap and stop-linked overlap are recorded separately. They are observational summaries of retained messages, not proof of works causing delays; no recorded message does not mean no disruption. Missing validity, unknown messages and overlapping cause families remain visible. Existing historical notice flags are not used as verified active-event labels.','',
 '### Raw archive and forecast-cutoff check','',
 f"The targeted cohort includes {raw['target_stops']:,} stops at six Munich hotspots and RE 161xx services on September 15. {raw['archive_observed_stops']:,} appear in retained September 14–16 responses. Works notes appear at some point for **{raw['works_recorded_anytime_stops']:,}** stops; **{raw['works_verified_before_cutoff_stops']:,}** have a non-deleted, validity-overlapping works note observed in the archive before the **stored** scheduled arrival minus five hours. This count must be rechecked against corrected per-trip schedules before it is used as a predictive feature.",'',
 'Archive recording timestamps supply a concrete route to historical receipt evidence. Coverage remains targeted and does not certify national direct-cause feature availability or delivery to the running app. Earlier source observations outside the scanned partitions may exist. Same-instant conflicting message versions require additional ambiguity checks before predictive use. No direct cause feature has been added.','',
 '## What the experiment can test next','',
 'Before fitting, resolve the confirmed trip-specific schedule mismatch. The proposed correction is to preserve raw per-trip planned-time snapshots with source recording timestamps, recompute delay labels against the approved schedule policy, and regenerate both training and evaluation features/labels consistently. Keep original facts/cache versions and report the correction effect separately. Until that policy is approved, labels remain unchanged and no fit begins. Use a July 22–August 22 training-date ramp from 1 to 1.5, with unweighted evaluation. Fit only the fine-tuned MLP and one classifier, producing the three selected candidate views. Record that existing leave-one-month-out historical notice folds use other training months, including dates after some historical training rows. The initial recency comparison is conditional on those retrospective folds; it does not validate point-in-time cause adaptation. A new recent-cause feature needs a separate strictly-past feature audit.','',
 'If the September change arose after the August 22 training cutoff, that ramp cannot learn it. A later chronological replay would need matched weighted/unweighted controls trained on the same later history, and remains a separately reported diagnostic experiment. September 15 and the later validation are reused, hypothesis-informed dates.','',
 '## Coverage and provenance limitations','',table(coverage,cf),'',
 'The initial streaming run records source file metadata and validates reference ordered IDs and labels. Metadata is weaker than content fingerprints, especially for SQLite WAL changes; final publication content hashes and a read-snapshot normal-control/terminal check are recorded separately. These do not retroactively prove that the original stream saw no transient edits. Some daily works counts were lost in the CSV-export failure and are shown as missing; all saved stop means were reconciled against the completed 45-date matrix during recovery. The initial run’s highest common observed stop is a last-common-stop metric, not a verified terminal. The separate terminal CSV resolves true final sequences and reports missing August terminal support explicitly. Scheduled time-of-day differences against September 15 are descriptive differences, not proof of timetable revisions. Cross-identity matching, verified physical early arrivals and nationwide cause receipt remain unresolved.','',
 f"Initial audit peak: {r['resources']['cgroup_peak_bytes']/2**20:.1f} MiB; raw scan peak: {raw['resources']['cgroup_peak_bytes']/2**20:.1f} MiB. Both use private 2 GiB limits and zero job swap. No fitting has started; no production pointer, endpoint or source fact was changed.",'',
 '[Per-trip averages and deviations](../data/ml/delay_shift_audit_20261013/trip-comparison.csv) · [Per-stop averages and deviations](../data/ml/delay_shift_audit_20261013/stop-comparison.csv) · [Early examples](../data/ml/delay_shift_audit_20261013/early-label-examples.csv) · [Raw source traces](../data/ml/delay_shift_audit_20261013/raw-early-plan-reconciliation.csv) · [Cause inventory](../data/ml/delay_shift_audit_20261013/cause-inventory.csv) · [Raw forecast-cutoff coverage](../data/ml/delay_shift_audit_20261013/raw-receipt-stop-coverage.csv)','']
 (ROOT/'docs/delay-shift-investigation.md').write_text('\n'.join(lines));print(json.dumps(group_summary,indent=2))
if __name__=='__main__':main()
